import type { Mock } from 'vitest';
/**
 * Test support for the OpenClaw Gateway protocol v4: the JSON Schemas exported
 * from the real openclaw TypeBox definitions (fixtures/openclaw-protocol-v4,
 * regenerated by scripts/sync-openclaw-protocol.mjs), frames captured from a
 * real gateway, builders whose output is validated against those schemas, and
 * a mock socket that validates every frame the client sends.
 */

import * as fs from 'fs';
import * as path from 'path';
import Ajv from 'ajv';
import type { ValidateFunction } from 'ajv';
import addFormats from 'ajv-formats';
import type { WebSocketLike } from '../../core/gatewayChatService';

const FIXTURE_DIR = path.join(__dirname, '..', 'fixtures', 'openclaw-protocol-v4');

type JsonObject = Record<string, unknown>;

function readJson(file: string): JsonObject {
    return JSON.parse(fs.readFileSync(path.join(FIXTURE_DIR, file), 'utf8')) as JsonObject;
}

const ajv = new Ajv({ strict: false, allErrors: true });
addFormats(ajv);
ajv.addSchema(readJson('handler-derived/display-message.json'), 'display-message.json');

const compiled = new Map<string, ValidateFunction>();

function validatorFor(file: string): ValidateFunction {
    let validate = compiled.get(file);
    if (!validate) {
        validate = ajv.compile(readJson(file));
        compiled.set(file, validate);
    }
    return validate;
}

/** The openclaw release the fixtures were exported from. */
export const FIXTURE_VERSION = fs.readFileSync(path.join(FIXTURE_DIR, 'VERSION'), 'utf8').trim();

