/** Methods whose results the fixtures do not model; any object is accepted. */
const UNMODELED_RESULTS = new Set(['chat.abort']);

function check(file: string, value: unknown, what: string): void {
    const validate = validatorFor(file);
    if (!validate(value)) {
        throw new Error(`${what} violates ${file}: ${ajv.errorsText(validate.errors)}\n${JSON.stringify(value)}`);
    }
}

function schemaFor(table: Record<string, string>, name: string, kind: string): string {
    const file = table[name];
    if (!file) {
        throw new Error(`no v4 ${kind} schema for "${name}"`);
    }
    return file;
}

/** A request frame the client sent, validated as a frame and by its method's params schema. */
export function assertValidRequest(raw: string): { id: string; method: string; params: JsonObject } {
    const frame = JSON.parse(raw) as { id: string; method: string; params: JsonObject };
    check('frame.request.json', frame, 'request frame');
    check(schemaFor(PARAMS_SCHEMAS, frame.method, 'params'), frame.params, `${frame.method} params`);
    return frame;
}

export function assertValidResult(method: string, payload: unknown): void {
    if (!UNMODELED_RESULTS.has(method)) {
        check(schemaFor(RESULT_SCHEMAS, method, 'result'), payload, `${method} result`);
    }
}

export function assertValidEvent(event: string, payload: unknown): void {
    check(schemaFor(EVENT_SCHEMAS, event, 'event'), payload, `${event} event`);
}

export function assertValidError(error: unknown): void {
    check('error-shape.json', error, 'error');
}

/* ---------------------------------------------------------------- */
/* Captured frames                                                   */
/* ---------------------------------------------------------------- */

export type CapturedFrame = { type: string; id?: string; event?: string; ok?: boolean; payload?: unknown; error?: unknown; seq?: number };

/** Frames recorded from a real openclaw gateway (see captured-frames.json). */
export const captured: Record<string, CapturedFrame> = JSON.parse(fs.readFileSync(path.join(FIXTURE_DIR, 'captured-frames.json'), 'utf8'));

/** A captured frame's payload, deep-copied so a test may modify it. */
export function capturedPayload(name: string): JsonObject {
    return JSON.parse(JSON.stringify(captured[name].payload)) as JsonObject;
}

/* ---------------------------------------------------------------- */
/* Validated frame builders                                          */
/* ---------------------------------------------------------------- */

export function eventFrame(event: string, payload: unknown, seq?: number): string {
    assertValidEvent(event, payload);
    const frame = { type: 'event', event, payload, ...(seq === undefined ? {} : { seq }) };
    check('frame.event.json', frame, 'event frame');
    return JSON.stringify(frame);
}

export function resultFrame(id: string, method: string, payload: unknown): string {
    assertValidResult(method, payload);
    const frame = { type: 'res', id, ok: true, payload };
    check('frame.response.json', frame, 'response frame');
    return JSON.stringify(frame);
}

export function errorFrame(id: string, error: unknown): string {
    assertValidError(error);
    return JSON.stringify({ type: 'res', id, ok: false, error });
}

export const CANONICAL_MAIN = 'agent:dev:main';

type Message = { role: string; text: string; seq?: number; runId?: string; id?: string; usage?: Record<string, number> };

/** A display message as the gateway projects transcript rows. */
export function displayMessage({ role, text, seq, runId, id, usage }: Message): JsonObject {
    const meta = { ...(id ? { id } : {}), ...(seq === undefined ? {} : { seq }), ...(runId ? { runId } : {}) };
    return {
        role,
        content: role === 'user' ? text : [{ type: 'text', text }],
        ...(usage ? { usage } : {}),
        __openclaw: meta,
    };
}

type RunRef = { runId: string; sessionKey?: string; seq: number };

/** Fields of an approval or question request a spec varies. */
type PromptRef = { id: string; sessionKey?: string | null; runId?: string | null; expiresAtMs?: number };

type WireQuestion = { questionId: string; question: string; header?: string; options?: Array<{ label: string; description?: string }>; multiSelect?: boolean; isOther?: boolean; isSecret?: boolean };

/** The gateway-clock stamps of prompt fixtures; their span is the lifetime a client times from receipt. */
export const PROMPT_CREATED_AT_MS = 1_790_606_196_000;
export const PROMPT_EXPIRES_AT_MS = 4_102_444_800_000;

function promptEnvelope({ id, expiresAtMs = PROMPT_EXPIRES_AT_MS }: PromptRef, request: JsonObject): JsonObject {
    return { id, request, createdAtMs: PROMPT_CREATED_AT_MS, expiresAtMs };
}

function promptSession({ sessionKey = CANONICAL_MAIN, runId = null }: PromptRef): JsonObject {
    return { sessionKey, runId, agentId: 'dev' };
}

