/* ---------------------------------------------------------------- */
/* Mock socket                                                       */
/* ---------------------------------------------------------------- */

export type MockSocket = WebSocketLike & {
    sent: string[];
    closed: Array<number | undefined>;
    emit(event: string, ...args: unknown[]): void;
    /** Requests the client sent, parsed; every one was validated against the v4 schemas. */
    requests(): Array<{ id: string; method: string; params: JsonObject }>;
    lastRequest(method: string): { id: string; method: string; params: JsonObject };
    /** Deliver a frame from the "gateway". */
    receive(frame: string): void;
    /** Answer the latest request of `method` with a validated result. */
    reply(method: string, payload: unknown): void;
    replyError(method: string, error: unknown): void;
};

/** Every request frame that failed validation, across all mock sockets; tests assert it stays empty. */
export const protocolViolations: string[] = [];

export function createMockSocket(): MockSocket {
    const handlers = new Map<string, Array<(...args: unknown[]) => void>>();
    const socket: MockSocket = {
        sent: [],
        closed: [],
        send(data: string) {
            try {
                assertValidRequest(data);
            } catch (err) {
                protocolViolations.push((err as Error).message);
            }
            socket.sent.push(data);
        },
        close(code?: number) {
            socket.closed.push(code);
            socket.emit('close', code ?? 1000, Buffer.alloc(0));
        },
        on(event: string, cb: (...args: never[]) => void) {
            handlers.set(event, [...(handlers.get(event) ?? []), cb as (...args: unknown[]) => void]);
        },
        removeListener(event: string, cb: (...args: unknown[]) => void) {
            handlers.set(event, (handlers.get(event) ?? []).filter((handler) => handler !== cb));
        },
        emit(event: string, ...args: unknown[]) {
            for (const handler of [...(handlers.get(event) ?? [])]) handler(...args);
        },
        requests() {
            return socket.sent.map((raw) => JSON.parse(raw) as { id: string; method: string; params: JsonObject });
        },
        lastRequest(method: string) {
            const request = socket.requests().filter((candidate) => candidate.method === method).pop();
            if (!request) throw new Error(`no ${method} request was sent`);
            return request;
        },
        receive(frame: string) {
            socket.emit('message', frame);
        },
        reply(method: string, payload: unknown) {
            socket.receive(resultFrame(socket.lastRequest(method).id, method, payload));
        },
        replyError(method: string, error: unknown) {
            socket.receive(errorFrame(socket.lastRequest(method).id, error));
        },
    };
    return socket;
}

/** Drive a handshake to hello-ok on a socket the client opened. */
export function completeHandshake(socket: MockSocket, hello: JsonObject = payloads.helloOk()): void {
    socket.receive(eventFrame('connect.challenge', payloads.challenge()));
    socket.reply('connect', hello);
}
